Rn = PolynomialRing(QQ, names=('n',)); (n,) = Rn._first_ngens(1)
Kn = Rn.fraction_field()
Rt = PolynomialRing(QQ, names=('t',)); (t,) = Rt._first_ngens(1)
Kt = Rt.fraction_field()
OD = OreAlgebra(Kt, 'Dt', names=('Dt',)); (Dt,) = OD._first_ngens(1)
theta = Kt(t)*Dt


def eval_poly_at_op(f, T):
    out = OD.zero()
    for a in reversed(Rn(f).list()):
        out = out*T + Kt(a)
    return out


def primitive_coefficients(c):
    c = [Kn(a) for a in c]
    den = Rn.one()
    for a in c:
        den = lcm(den, Rn(a.denominator()))
    nums = [Rn(den*a) for a in c]
    g = nums[_sage_const_0 ]
    for a in nums[_sage_const_1 :]:
        g = gcd(g, a)
    nums = [a.quo_rem(g)[_sage_const_0 ] for a in nums]
    scl = QQ(_sage_const_1 )/QQ(nums[-_sage_const_1 ].leading_coefficient())
    return [Rn(scl*a) for a in nums]


def right_quo_rem(P, Q):
    P = OD(P)
    Q = OD(Q)
    quo = OD.zero()
    rem = P
    while rem != _sage_const_0  and rem.order() >= Q.order():
        k = rem.order()-Q.order()
        a = rem[rem.order()]/Q[Q.order()]
        term = Kt(a)*Dt**k
        quo += term
        rem -= term*Q
    return quo, rem


def apply_op(L, f):
    f = Kt(f)
    ans = Kt(_sage_const_0 )
    der = f
    for k in range(L.order()+_sage_const_1 ):
        if k == _sage_const_0 :
            der = f
        elif k == _sage_const_1 :
            der = f.derivative()
        else:
            der = der.derivative()
        ans += Kt(L[k])*der
    return ans


def conjugate_by_log_derivative(L, ell):
    """Return g^(-1) L g when g'/g = ell."""
    P = Dt + Kt(ell)
    out = OD.zero()
    power = OD.one()
    for k in range(L.order()+_sage_const_1 ):
        if k > _sage_const_0 :
            power *= P
        out += Kt(L[k])*power
    return out


