def polynomial_solutions_of_gauged_operator(Lg, maxdeg):
    """Find P(t), deg P<=maxdeg, with Lg(P)=0 by exact linear algebra."""
    vals = [apply_op(Lg, Kt(t**i)) for i in range(maxdeg+_sage_const_1 )]
    den = Rt.one()
    for v in vals:
        den = lcm(den, Rt(Kt(v).denominator()))
    polys = [Rt(den*v) for v in vals]
    md = max((f.degree() if f else -_sage_const_1 ) for f in polys)
    M = matrix(QQ, md+_sage_const_1 , maxdeg+_sage_const_1 ,
               lambda row, col: polys[col][row] if row <= polys[col].degree() else _sage_const_0 )
    ans = []
    for vec in M.right_kernel().basis():
        P = Rt(sum(vec[i]*t**i for i in range(maxdeg+_sage_const_1 )))
        if P and apply_op(Lg, Kt(P)) == _sage_const_0 :
            ans.append(P)
    return ans

