def rh(z):
    return Kn(_sage_const_2 )**(-_sage_const_20 )*(z+_sage_const_3 )**_sage_const_4 *(z+_sage_const_4 )**_sage_const_6  / (
        (z+QQ(_sage_const_5 )/_sage_const_2 )**_sage_const_4 *(z+QQ(_sage_const_7 )/_sage_const_2 )**_sage_const_3 *(z+QQ(_sage_const_9 )/_sage_const_2 )**_sage_const_3 
    )

def hquot(j):
    out = Kn(_sage_const_1 )
    for k in range(j):
        out *= rh(n+k)
    return out

def mellin_from_rational_coeffs(c):
    pp = primitive_coefficients(c)
    MM = OD.zero()
    for j in range(_sage_const_4 ):
        MM += Kt(t**j)*eval_poly_at_op(pp[j], -theta-j-_sage_const_1 )
    return pp, MM

for label, coeffs in [
    ('u_n = h_n v_n', [crat[j]*hquot(j) for j in range(_sage_const_4 )]),
    ('u_n = v_n/h_n', [crat[j]/hquot(j) for j in range(_sage_const_4 )]),
]:
    pp, MM = mellin_from_rational_coeffs(coeffs)
    print('\n===', label, '===')
    print('primitive degrees =', [f.degree() for f in pp])
